import{_ as s,C as o,o as a,c as n,ag as t,E as l}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Seller Storefront","description":"","frontmatter":{},"headers":[],"relativePath":"storefront/seller-storefront.md","filePath":"storefront/seller-storefront.md","lastUpdated":1787563966000}'),i={name:"storefront/seller-storefront.md"};function g(h,e,p,c,d,u){const r=o("ImagePopup");return a(),n("div",null,[e[0]||(e[0]=t('<h1 id="seller-storefront" tabindex="-1">Seller Storefront <a class="header-anchor" href="#seller-storefront" aria-label="Permalink to &quot;Seller Storefront&quot;">​</a></h1><p>Every approved seller gets a public store page on your storefront, and every product page tells shoppers who is selling it. This is the marketplace as a customer experiences it — browsing a seller, comparing sellers on one product, and checking out with items from several at once.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What a seller&#39;s store page shows</li><li>How shoppers compare sellers on the same product</li><li>What changes in the cart when several sellers are involved</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Store pages depend on &quot;Show Publicly&quot;</p><p>Seller store pages only appear when <strong>Show Publicly</strong> is enabled under <strong>Configure → Marketplace → Sellers → Registration &amp; Visibility</strong>. With it off, sellers still sell, but they have no public page.</p></div><h2 id="the-seller-s-store-page" tabindex="-1">The seller&#39;s store page <a class="header-anchor" href="#the-seller-s-store-page" aria-label="Permalink to &quot;The seller&#39;s store page&quot;">​</a></h2><p>A store page carries the seller&#39;s banner and logo from <a href="/sellers/seller-profile">Manage Profile</a>, their business name, address and star rating.</p><p>Three tabs run across it — <strong>Products</strong>, <strong>Reviews</strong> and <strong>About</strong>, the first two showing their counts — and a row of actions sits alongside: <strong>Share</strong>, <strong>Contact</strong>, and <strong>Report Issue</strong>.</p>',7)),l(r,{src:"/images/seller-storefront/seller-store.png",alt:"A seller's public store page with banner, product and review counts, and their catalog"}),e[1]||(e[1]=t('<h3 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h3><p>The seller&#39;s catalog, with <strong>Search for Products</strong> across it and the browsing controls shoppers expect:</p><ul><li><strong>Sort By</strong> — <strong>Cheapest First</strong>, <strong>Expensive First</strong>, <strong>From A-Z</strong>, <strong>From Z-A</strong>, <strong>Newest First</strong>, <strong>Oldest First</strong>.</li><li><strong>Filters</strong> — including a <strong>Price Range</strong>, with <strong>Clear All</strong> to reset them.</li><li><strong>Show</strong> — how many products per page.</li></ul><p>A seller with nothing approved yet shows <strong>No products available here</strong>.</p><h3 id="reviews" tabindex="-1">Reviews <a class="header-anchor" href="#reviews" aria-label="Permalink to &quot;Reviews&quot;">​</a></h3><p>Shoppers rate the seller with a <strong>Rating</strong>, a <strong>Title</strong> and a <strong>Comment</strong> from <strong>Write a Review</strong>, and read existing feedback under <strong>Customer Reviews</strong> with <strong>View All Reviews</strong>.</p><p>Three rules apply, and each is explained on the spot when it stops someone:</p><ul><li>A shopper must be <strong>signed in</strong> to review.</li><li>A shopper must have <strong>ordered</strong> from the seller.</li><li>A shopper can review a given seller <strong>once</strong>.</li></ul><p>Reviews stay hidden until the admin approves them — see <a href="/moderation/rating-management">Rating Management</a>.</p><h3 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h3><p>The seller&#39;s own words, taken straight from their profile: <strong>About Us</strong>, <strong>Return Policy</strong>, <strong>Shipping Policy</strong>, and <strong>Privacy Policy</strong>, with a <strong>Download</strong> option where the seller has attached a document.</p><h2 id="contacting-and-reporting-a-seller" tabindex="-1">Contacting and reporting a seller <a class="header-anchor" href="#contacting-and-reporting-a-seller" aria-label="Permalink to &quot;Contacting and reporting a seller&quot;">​</a></h2><p><strong>Share</strong>, <strong>Contact</strong> and <strong>Report Issue</strong> sit together beside the tabs.</p><ul><li><strong>Share</strong> — a <strong>Share On</strong> panel with the usual networks.</li><li><strong>Contact</strong> — a short form (<strong>Name</strong>, <strong>Email</strong>, <strong>Subject</strong>, <strong>Query</strong>) that sends the shopper&#39;s message to the seller, confirming when the query has been submitted. It&#39;s rate-limited, so it can&#39;t be used to flood a seller.</li><li><strong>Report Issue</strong> — the shopper picks a <strong>Reason</strong> from the list the admin maintains, or chooses <strong>Other Reason</strong> and describes it. The same three rules as reviews apply: signed in, has ordered, once only. See <a href="/moderation/seller-product-flagging">Seller &amp; Product Flagging</a>.</li></ul><h2 id="on-a-product-page" tabindex="-1">On a product page <a class="header-anchor" href="#on-a-product-page" aria-label="Permalink to &quot;On a product page&quot;">​</a></h2><p>Every product page names its seller under <strong>Sold By</strong>, with a <strong>Seller Information</strong> panel that expands with <strong>More Information</strong> and collapses with <strong>Hide</strong>, and a <strong>Top Selling</strong> strip of that seller&#39;s other products.</p><p>Where more than one seller carries the same product, the page says so — <em>:count more seller selling same product</em> — and links to the offers view.</p><p><strong>Report Product</strong> works exactly like Report Issue above, against the listing rather than the seller.</p><h2 id="comparing-offers" tabindex="-1">Comparing offers <a class="header-anchor" href="#comparing-offers" aria-label="Permalink to &quot;Comparing offers&quot;">​</a></h2><p>The offers view lists every seller carrying a product, each with their own price, condition and description, and its own <strong>Add to Cart</strong>; a downloadable product also shows that seller&#39;s <strong>links</strong> and <strong>samples</strong>. Where there are more sellers than fit, a <strong>Load More</strong> control fetches the next batch.</p><p>This is the customer-facing side of <a href="/catalog/selling-existing-products">Selling Existing Products</a>: each row is one seller&#39;s offer on the same catalog product.</p><h2 id="one-cart-several-sellers" tabindex="-1">One cart, several sellers <a class="header-anchor" href="#one-cart-several-sellers" aria-label="Permalink to &quot;One cart, several sellers&quot;">​</a></h2><p>A shopper can fill a single cart from several sellers and the admin, and check out once. Two things behave differently from a single-seller store:</p><ul><li><strong>Sold By</strong> appears on each cart line, so the shopper can see which items come from where.</li><li><strong>Seller Coupons</strong> get their own box, separate from the store-wide coupon field. A shopper entering a seller&#39;s code in the wrong box is told to use the other one, and a code that matches nothing in the cart says so. See <a href="/marketing/checkout-deals">Checkout Deals</a>.</li></ul><p>Where a seller has a <strong>Minimum Order Amount</strong>, the cart tells the shopper what that seller&#39;s minimum is until it&#39;s met.</p><div class="info custom-block"><p class="custom-block-title">Sellers browsing their own storefront</p><p>A signed-in seller looking at the storefront gets a <strong>Switch to manage store</strong> link in the header, straight back to their <a href="/sellers/seller-dashboard">Dashboard</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The store page is built almost entirely from things the seller controls — banner, description, policies, and approved reviews. A seller asking why their page looks empty is usually a seller who hasn&#39;t finished <a href="/sellers/seller-profile">Manage Profile</a>.</p></div>',27))])}const w=s(i,[["render",g]]);export{f as __pageData,w as default};
